<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Category; use App\Models\Product; use App\Models\ProductImage; use App\Models\ProductVariant; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class ProductController extends Controller {
private function validateData(Request $r):array{return $r->validate(['category_id'=>'required|exists:categories,id','name'=>'required|string|max:190','sku'=>'required|string|max:80|unique:products,sku,'.optional($r->route('product'))->id,'slug'=>'nullable|string|max:190','short_description'=>'nullable|string|max:500','description'=>'nullable|string','price'=>'required|numeric|min:0','compare_price'=>'nullable|numeric|min:0','stock'=>'required|integer|min:0','image_file'=>'nullable|image|max:3072','gallery_files.*'=>'nullable|image|max:3072','delete_image_ids.*'=>'nullable|integer','variant_name.*'=>'nullable|string|max:120','variant_sku.*'=>'nullable|string|max:80','variant_color.*'=>'nullable|string|max:80','variant_size.*'=>'nullable|string|max:80','variant_price.*'=>'nullable|numeric|min:0','variant_stock.*'=>'nullable|integer|min:0','is_active'=>'nullable|boolean','is_featured'=>'nullable|boolean']);}
public function index(Request $r){$q=Product::with('category')->withCount(['images','variants']);if($r->filled('q'))$q->where('name','like','%'.$r->q.'%');return view('admin.products.index',['products'=>$q->latest()->paginate(20)->withQueryString()]);}
public function create(){return view('admin.products.form',['product'=>new Product,'categories'=>Category::orderBy('name')->get()]);}
public function store(Request $r){$d=$this->validateData($r);if($r->hasFile('image_file'))$d['image']=$r->file('image_file')->store('products','public');$d['slug'] = !empty($d['slug'])
    ? Str::slug($d['slug'])
    : Str::slug($d['name']).'-'.Str::lower(Str::random(5));$d['is_active']=$r->boolean('is_active');$d['is_featured']=$r->boolean('is_featured');$p=Product::create($d);$this->syncExtras($r,$p);return redirect()->route('admin.products.edit',$p)->with('success','Product created.');}
public function edit(Product $product){$product->load(['images','variants']);return view('admin.products.form',['product'=>$product,'categories'=>Category::orderBy('name')->get()]);}
public function update(Request $r,Product $product){$d=$this->validateData($r);if($r->hasFile('image_file')){if($product->image)Storage::disk('public')->delete($product->image);$d['image']=$r->file('image_file')->store('products','public');}$d['slug'] = !empty($d['slug'])
    ? Str::slug($d['slug'])
    : $product->slug;$d['is_active']=$r->boolean('is_active');$d['is_featured']=$r->boolean('is_featured');$product->update($d);$this->syncExtras($r,$product);return back()->with('success','Product updated.');}
public function destroy(Product $product){if($product->image)Storage::disk('public')->delete($product->image);foreach($product->images as $img)Storage::disk('public')->delete($img->path);$product->delete();return back()->with('success','Product deleted.');}
public function deleteImage(Product $product,ProductImage $image){abort_unless($image->product_id===$product->id,404);Storage::disk('public')->delete($image->path);$image->delete();return back()->with('success','Image removed.');}
private function syncExtras(Request $r,Product $p):void{foreach((array)$r->input('delete_image_ids',[]) as $imageId){$img=$p->images()->find($imageId);if($img){Storage::disk('public')->delete($img->path);$img->delete();}}if($r->hasFile('gallery_files'))foreach($r->file('gallery_files') as $i=>$file)ProductImage::create(['product_id'=>$p->id,'path'=>$file->store('products/gallery','public'),'sort_order'=>$p->images()->count()+$i]);$names=$r->input('variant_name',[]);$ids=$r->input('variant_id',[]);$seen=[];foreach($names as $i=>$name){if(!$name)continue;$payload=['product_id'=>$p->id,'name'=>$name,'sku'=>$r->input("variant_sku.$i")?:$p->sku.'-'.($i+1).'-'.Str::upper(Str::random(3)),'color'=>$r->input("variant_color.$i"),'size'=>$r->input("variant_size.$i"),'price'=>$r->input("variant_price.$i")?:null,'stock'=>(int)($r->input("variant_stock.$i")?:0),'is_active'=>true];if(!empty($ids[$i])){$v=$p->variants()->find($ids[$i]);if($v){$v->update($payload);$seen[]=$v->id;continue;}}$seen[]=ProductVariant::create($payload)->id;}if($r->boolean('replace_variants'))$p->variants()->whereNotIn('id',$seen)->delete();}
}
